import React from 'react';
import { ArrowUpRight, ArrowDownRight, Minus } from 'lucide-react';

interface StatCardProps {
  title: string;
  value: string | number | React.ReactNode;
  subValue?: string;
  trend?: 'up' | 'down' | 'neutral';
  trendValue?: string;
  icon: React.ReactNode;
  colorClass?: string;
  isDark?: boolean;
}

export const StatCard: React.FC<StatCardProps> = ({ 
  title, 
  value, 
  subValue, 
  trend, 
  trendValue, 
  icon,
  colorClass = "text-orange-500",
  isDark = true
}) => {
  return (
    <div className={`${
      isDark 
        ? 'bg-card border-slate-700/50 hover:border-orange-500/50' 
        : 'bg-white border-slate-200 hover:border-orange-500/30'
      } rounded-xl p-6 border shadow-sm transition-all duration-300`}>
      <div className="flex justify-between items-start mb-4">
        <div className={`p-3 rounded-lg ${isDark ? 'bg-slate-800' : 'bg-slate-50'} ${colorClass} bg-opacity-20`}>
          {icon}
        </div>
        {trend && (
          <div className={`flex items-center text-xs font-medium px-2 py-1 rounded-full ${
            trend === 'up' ? 'text-emerald-500 bg-emerald-500/10' : 
            trend === 'down' ? 'text-rose-500 bg-rose-500/10' : 'text-slate-500 bg-slate-500/10'
          }`}>
            {trend === 'up' && <ArrowUpRight className="w-3 h-3 mr-1" />}
            {trend === 'down' && <ArrowDownRight className="w-3 h-3 mr-1" />}
            {trend === 'neutral' && <Minus className="w-3 h-3 mr-1" />}
            {trendValue}
          </div>
        )}
      </div>
      <h3 className={`${isDark ? 'text-slate-400' : 'text-slate-500'} text-sm font-medium mb-1`}>{title}</h3>
      <div className="flex items-baseline gap-2">
        <div className={`text-2xl font-bold w-full ${isDark ? 'text-white' : 'text-slate-900'}`}>{value}</div>
        {subValue && <span className={`${isDark ? 'text-slate-500' : 'text-slate-400'} text-xs whitespace-nowrap`}>{subValue}</span>}
      </div>
    </div>
  );
};

import React from 'react';
import {
  AreaChart, Area, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer,
  BarChart, Bar, Legend
} from 'recharts';
import { MonthlyData } from '../types';

interface ChartProps {
  data: MonthlyData[];
  isDark?: boolean;
}

const CustomTooltip = ({ active, payload, label, isDark }: any) => {
  if (active && payload && payload.length) {
    return (
      <div className={`${isDark ? 'bg-slate-800 border-slate-700 text-slate-200' : 'bg-white border-slate-200 text-slate-800'} border p-3 rounded-lg shadow-xl`}>
        <p className="font-semibold mb-2">{label}</p>
        {payload.map((entry: any, index: number) => (
          <p key={index} className="text-sm" style={{ color: entry.color }}>
            {entry.name}: <span className="font-bold">{entry.value}</span>
          </p>
        ))}
      </div>
    );
  }
  return null;
};

export const TrafficChart: React.FC<ChartProps> = ({ data, isDark = true }) => {
  const axisColor = isDark ? '#94a3b8' : '#64748b';
  const gridColor = isDark ? '#334155' : '#e2e8f0';

  return (
    <div className="h-[250px] w-full">
      <h3 className="text-md font-semibold text-orange-500 mb-4">Traffic Trends</h3>
      <ResponsiveContainer width="100%" height="100%">
        <AreaChart data={data} margin={{ top: 10, right: 10, left: -20, bottom: 0 }}>
          <defs>
            <linearGradient id="colorTraffic" x1="0" y1="0" x2="0" y2="1">
              <stop offset="5%" stopColor="#f97316" stopOpacity={0.3}/>
              <stop offset="95%" stopColor="#f97316" stopOpacity={0}/>
            </linearGradient>
          </defs>
          <CartesianGrid strokeDasharray="3 3" stroke={gridColor} vertical={false} />
          <XAxis dataKey="month" stroke={axisColor} fontSize={12} tickLine={false} axisLine={false} />
          <YAxis stroke={axisColor} fontSize={12} tickLine={false} axisLine={false} />
          <Tooltip content={<CustomTooltip isDark={isDark} />} />
          <Area 
            type="monotone" 
            dataKey="traffic" 
            stroke="#f97316" 
            strokeWidth={3}
            fillOpacity={1} 
            fill="url(#colorTraffic)" 
            name="Visitors"
            activeDot={{ r: 6 }}
          />
        </AreaChart>
      </ResponsiveContainer>
    </div>
  );
};

export const VideosChart: React.FC<ChartProps> = ({ data, isDark = true }) => {
  const axisColor = isDark ? '#94a3b8' : '#64748b';
  const gridColor = isDark ? '#334155' : '#e2e8f0';

  return (
    <div className="h-[200px] w-full">
      <h3 className="text-md font-semibold text-amber-500 mb-4">Benchmark Videos</h3>
